import math

class Solution:
    def repeatedStringMatch(self, a: str, b: str) -> int:
        count = math.ceil(len(b) / len(a))
        if b in a * count:
            return count
        if b in a * (count + 1):
            return count + 1
        return -1

class Solution {
public:
    int repeatedStringMatch(string a, string b) {
        int count = (b.size() + a.size() - 1) / a.size();
        string s = "";
        for (int i = 0; i < count; i++) s += a;
        if (s.find(b) != string::npos) return count;
        s += a;
        if (s.find(b) != string::npos) return count + 1;
        return -1;
    }
};

class Solution {
    public int repeatedStringMatch(String a, String b) {
        int count = (b.length() + a.length() - 1) / a.length();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) sb.append(a);
        if (sb.indexOf(b) != -1) return count;
        sb.append(a);
        if (sb.indexOf(b) != -1) return count + 1;
        return -1;
    }
}

var repeatedStringMatch = function(a, b) {
    const count = Math.ceil(b.length / a.length);
    const s1 = a.repeat(count);
    if (s1.includes(b)) return count;
    const s2 = s1 + a;
    if (s2.includes(b)) return count + 1;
    return -1;
};
